const items = $input.all();
const rows = items.map(i => Object.values(i.json));
let pronto = false;
for (const row of rows) {
  const cells = row.map(c => (c ?? '').toString().trim());
  if (cells[0] === 'STATUS GERAL') {
    const statusCell = cells.find((c, i) => i > 0 && c !== '');
    pronto = statusCell === 'OK';
    break;
  }
}
return [{ json: { pronto } }];

function parseBRL(v){
  if (v === null || v === undefined) return null;
  let s = String(v).trim();
  if (s === '' || s === '-' || s === '—') return null;
  let neg = false;
  if (s.startsWith('(') && s.endsWith(')')) { neg = true; s = s.slice(1,-1); }
  const n = parseFloat(s.replace(/[^\d,.\-]/g,'').replace(/\./g,'').replace(',', '.'));
  if (isNaN(n)) return null;
  return neg ? -n : n;
}
function parsePct(v){
  if (!v) return 0;
  const n = parseFloat(String(v).replace('%','').replace(',', '.'));
  return isNaN(n) ? 0 : n;
}
function parseInt_(v){
  if (!v) return 0;
  const n = parseInt(String(v).replace(/[^\d\-]/g,''), 10);
  return isNaN(n) ? 0 : n;
}
function nonblank(row){ return row.filter(c => c !== '' && c !== null && c !== undefined); }
function dedupe(row){
  const out = [];
  for (const c of row) if (out.length === 0 || out[out.length-1] !== c) out.push(c);
  return out;
}
function clean(v){ return (v ?? '').toString().trim(); }
function getRaw(nodeName){
  const items = $('Ler ' + nodeName).all();
  return items.map(i => Object.values(i.json));
}

// ---- Dashboard KPIs + Estoque por status ----
const dashRows = getRaw('Dashboard').map(r => r.map(clean));
const kv = {};
for (let i = 0; i < dashRows.length - 1; i++) {
  const labels = nonblank(dedupe(dashRows[i]));
  if (!labels.length) continue;
  if (labels.some(c => /^(R\$|-|\d)/.test(c))) continue;
  const values = nonblank(dedupe(dashRows[i+1]));
  if (values.length === labels.length && JSON.stringify(values) !== JSON.stringify(labels)) {
    labels.forEach((lab, idx) => { if (!(lab in kv)) kv[lab] = values[idx]; });
  }
}
const kpis = {
  faturamento: parseBRL(kv['FATURAMENTO']),
  lucroLiquido: parseBRL(kv['LUCRO LÍQUIDO']),
  saldoCaixa: parseBRL(kv['SALDO DE CAIXA']) ?? 0,
  capitalEstoque: parseBRL(kv['CAPITAL EM ESTOQUE']) ?? 0,
  pecasEstoque: parseInt_(kv['PEÇAS EM ESTOQUE']),
  margemLiquida: parsePct(kv['MARGEM LÍQUIDA']),
  dividaSocio: parseBRL(kv['DÍVIDA COM SÓCIO']) ?? 0,
  patrimonioBruto: parseBRL(kv['PATRIMÔNIO BRUTO']) ?? 0,
  patrimonioLiquido: parseBRL(kv['PATRIMÔNIO LÍQUIDO']) ?? 0,
};

let estoquePorStatus = [];
for (let i = 0; i < dashRows.length; i++) {
  const nb = nonblank(dashRows[i]);
  if (nb[0] === 'Status' && nb[1] === 'Quantidade') {
    for (let j = i+1; j < dashRows.length; j++) {
      const nb2 = nonblank(dashRows[j]);
      if (nb2.length < 2) break;
      estoquePorStatus.push({ status: nb2[0], qtd: parseInt_(nb2[1]) });
    }
    break;
  }
}

let mesAnalisado = null;
for (const row of dashRows) {
  const idx = row.indexOf('Mês analisado');
  if (idx !== -1 && row[idx+1]) { mesAnalisado = row[idx+1]; break; }
}

// ---- Relógios ----
const relRows = getRaw('Relógios').map(r => r.map(clean));
const watches = relRows.filter(r => r[0] && r[0].startsWith('TCC')).map(cells => ({
  itemId: cells[0], marca: cells[1], modelo: cells[2], referencia: cells[3],
  condicao: cells[4], status: cells[5], dataCompra: cells[6], dataEntrada: cells[7],
  dataVenda: cells[8], canal: cells[9], precoAnuncio: cells[10],
  custoCompleto: cells[11], vendaBruta: cells[12], deducoes: cells[13],
  lucroLiquido: cells[14], margem: cells[15],
  dias: cells[16] ? parseInt_(cells[16]) : null,
  lote: cells[17], observacoes: cells[18],
}));

// ---- Lançamentos ----
const lancHeader = ['id','dataCompetencia','dataCaixa','itemId','lote','descricao','natureza',
  'grupoDre','categoria','contraparte','conta','forma','moeda','valorOriginal','cambio','valorBRL',
  'status','vencimento','documento','observacoes','centroCusto','tratamento','precisaoData'];
const lancRows = getRaw('Lançamentos').map(r => r.map(clean));
const lancamentos = lancRows.filter(r => r[0] && r[0].startsWith('LCT-'))
  .map(cells => {
    const obj = {};
    lancHeader.forEach((h, i) => obj[h] = cells[i] ?? '');
    return obj;
  });

// ---- DRE mensal ----
const dreRows = getRaw('DRE').map(r => r.map(clean));
const dreHeaderIdx = dreRows.findIndex(r => r[0] === 'Mês' && r[1] && r[1].startsWith('Receita'));
const dreMensal = (dreHeaderIdx === -1 ? [] : dreRows.slice(dreHeaderIdx + 1))
  .filter(r => r[0] && r.length >= 9)
  .map(row => ({
    mes: row[0],
    receitaBruta: parseBRL(row[1]) ?? 0,
    deducoes: parseBRL(row[2]) ?? 0,
    receitaLiquida: parseBRL(row[3]) ?? 0,
    cmv: parseBRL(row[4]) ?? 0,
    lucroBruto: parseBRL(row[5]) ?? 0,
    despesasOp: parseBRL(row[6]) ?? 0,
    resultadoLiquido: parseBRL(row[7]) ?? 0,
    margemLiquida: parsePct(row[8]),
  }));

// ---- Fluxo de caixa ----
const fxRows = getRaw('Fluxo de Caixa').map(r => r.map(clean));
const fxHeaderIdx = fxRows.findIndex(r => r[0] === 'Mês' && r[1] && r[1].startsWith('Entradas'));
const fluxoCaixa = (fxHeaderIdx === -1 ? [] : fxRows.slice(fxHeaderIdx + 1))
  .filter(r => r[0] && r.length >= 5)
  .map(row => ({
    mes: row[0],
    entradas: parseBRL(row[1]) ?? 0,
    saidas: parseBRL(row[2]) ?? 0,
    saldoMes: parseBRL(row[3]) ?? 0,
    saldoAcumulado: parseBRL(row[4]) ?? 0,
  }));

const snapshot = {
  updatedAt: new Date().toISOString(),
  mesAnalisado,
  kpis,
  estoquePorStatus,
  watches,
  lancamentos,
  dreMensal,
  fluxoCaixa,
};

return [{ json: {
  content: Buffer.from(JSON.stringify(snapshot, null, 2), 'utf-8').toString('base64'),
  snapshot,
} }];
